// Lookahead buffer is used to track free blocks efficiently
// We scan the lookahead buffer for a free block, then update it
// Wear leveling is achieved by rotating through blocks and avoiding excessive writes to same block

if (lfs->free.off >= lfs->free.size) {
    // Need to refill lookahead buffer
    lfs->free.off = 0;
    lfs->free.count = 0;

    // Scan all blocks from 0 to lfs->block_count for free blocks
    // We use a simple linear scan with wear-leveling by starting at lfs->free.cursor
    lfs_block_t block = lfs->free.cursor;
    lfs_block_t end = lfs->block_count;
    lfs_block_t start = block;

    do {
        // Check if block is free by reading its tag
        lfs_tag_t tag;
        int err = lfs_bd_read(lfs, &tag, block, 0, sizeof(tag));
        if (err) {
            return err;
        }

        // If tag is erased (all 0xFF) or has no type, it's free
        if (tag == LFS_MKTAG(0, 0, 0) || (tag & LFS_MKTAG(0x800, 0, 0)) == 0) {
            if (lfs->free.count < LFS_LOOKAHEAD_SIZE) {
                lfs->free.buffer[lfs->free.count++] = block;
            }
        }

        block = (block + 1) % lfs->block_count;
    } while (block != start);

    // If no free blocks found, return error
    if (lfs->free.count == 0) {
        return LFS_ERR_NOSPC;
    }
}

// Pick the next block from lookahead buffer
*block = lfs->free.buffer[lfs->free.off];
lfs->free.off++;

// Update cursor for wear leveling
lfs->free.cursor = (*block + 1) % lfs->block_count;

return LFS_ERR_OK;

